shell_commands:
node -e "
import {readdirSync, readFileSync} from 'node:fs';
const base = 'node_modules/@re-cinq/eslint-plugin-re-lint';
console.log(readdirSync(base, {recursive: true}));
"

node -e "
import {readFileSync} from 'node:fs';
for (const name of ['require-colocated-tests', 'test-imports-its-subject', 'require-spec-link', 'max-expects']) {
  console.log('=== ' + name + ' ===');
  console.log(readFileSync('node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/' + name + '.mjs', 'utf8'));
}
"

